"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["28762"],{14638(e){e.exports=JSON.parse('{"id":"FIN-058","slug":"real-interest-rate","term":"Real Interest Rate","also_known_as":[],"difficulty":"Beginner","definition":"The real interest rate is the interest rate after adjusting for inflation. It shows how much your purchasing power actually grows when you save, or how much borrowing really costs.","explanation":["Interest rates are usually quoted in nominal terms, but inflation reduces what money can buy. The real interest rate removes the effect of rising prices so you can see the true gain or cost.","A simple approximation is to subtract inflation from the nominal rate. If a savings account pays 5% and inflation is 3%, the real interest rate is about 2%. Your balance grows by 5%, but because prices have risen by 3%, you can buy only about 2% more than before. The precise figure is slightly lower, about 1.94%, but the simple subtraction is close enough for most purposes.","Real interest rates can be negative. If savings pay 2% while inflation is 5%, the real rate is about \u22123%, meaning savers lose purchasing power even as their balances grow.","For borrowers, the effect is reversed. High inflation reduces the real burden of fixed-rate debt, because repayments are made with money that is worth less. Central banks watch real interest rates closely, because they shape decisions to save, borrow and invest."],"note":"","total":1500,"prev":{"slug":"real-gdp","term":"Real GDP"},"next":{"slug":"real-option","term":"Real Option"}}')}}]);